  void register({
    required String name,
    required String baseUrl,
    Duration? connect,
    Duration? streamIdle,
  }) {
    final entry = ProviderTuningEntry(
      name: name,
      baseUrl: baseUrl,
      connect: connect,
      streamIdle: streamIdle,
