    apiKeyEnv: (apiKeyEnv != null && apiKeyEnv.trim().isNotEmpty)
        ? apiKeyEnv.trim()
        : resolved.keyName,
    contextWindow: contextWindow,
    maxTokens: maxTokens,
    ref: name,
  );
}

