    if (apiKeyEnv != null) 'apiKeyEnv': apiKeyEnv,
    if (contextWindow != null) 'contextWindow': contextWindow,
    if (maxTokens != null) 'maxTokens': maxTokens,
    if (connectTimeout != null)
